INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38461, 'Numbers 33:9', 'Numbers', 33, 9, 'بیا هغوی په ایلیم کې خېمې ودرولې چېرته چې د اوبو دولس چینې او اویا د خرما ونې وې.', 'بیا هغوی په ایلیم کې خېمې ودرولې چېرته چې د اوبو دولس چینې او اویا د خرما ونې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38462, 'Numbers 33:10', 'Numbers', 33, 10, 'هغوی د ایلیم څخه لاړل او د سرې بحیرې په غاړه یې خېمې ودرولې.', 'هغوی د ایلیم چخه لارل او د سرې بحیرې په غاره یې خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38463, 'Numbers 33:11', 'Numbers', 33, 11, 'د سرې بحیرې څخه روان شول او د سین په دښته کې یې خېمې ودرولې.', 'د سرې بحیرې چخه روان شول او د سین په دشته کې یې خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38464, 'Numbers 33:12', 'Numbers', 33, 12, 'بیا د سین د دښتې څخه لاړل او په دفقه کې یې خېمې ودرولې.', 'بیا د سین د دشتې چخه لارل او په دفقه کې یې خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38465, 'Numbers 33:13', 'Numbers', 33, 13, 'د دفقه څخه لاړل او په الوش کې یې خېمې ودرولې.', 'د دفقه چخه لارل او په الوش کې یې خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38466, 'Numbers 33:14', 'Numbers', 33, 14, 'د الوش څخه لاړل او په رفیدیم کې یې خېمې ودرولې، چېرته چې د خلکو دپاره د څښلو اوبه نه وې.', 'د الوش چخه لارل او په رفیدیم کې یې خېمې ودرولې، چېرته چې د خلکو دپاره د چشلو اوبه نه وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38467, 'Numbers 33:15', 'Numbers', 33, 15, 'هغوی د رفیدیم څخه لاړل او په اخر کې د سینا دښتې ته ورسېدل.', 'هغوی د رفیدیم چخه لارل او په اخر کې د سینا دشتې ته ورسېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_33_15.mp3', 'https://drive.google.com/file/d/1iueNzXGD59Ph0NqjT71RNuS55dymE3ka/preview', 1761237839, 1761237839),
(38468, 'Numbers 33:37', 'Numbers', 33, 37, 'کله چې هغوی د قادش څخه لاړل، نو د هور د غره په څنګ کې یې د ادوم په سرحد کې خېمې ودرولې.', 'کله چې هغوی د قادش چخه لارل، نو د هور د غره په چنګ کې یې د ادوم په سرحد کې خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38469, 'Numbers 33:38', 'Numbers', 33, 38, 'دا هغه ځای دی چې څښتن هارون کاهن ته امر وکړ چې د غره سرته وخېژي. هارون هلته د پنځمې میاشتې په لومړۍ ورځ څلوېښت کاله وروسته له دې چې اسراییلیان د مصر څخه تللي وو، مړ شو.', 'دا هغه جای دی چې چشتن هارون کاهن ته امر وکر چې د غره سرته وخېژی. هارون هلته د پنجمې میاشتې په لومری ورج چلوېشت کاله وروسته له دې چې اسراییلیان د مصر چخه تللی وو، مر شو.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38470, 'Numbers 33:39', 'Numbers', 33, 39, 'په هغه وخت کې هارون د یوسلو درویشتو کالو په عمر ؤ.', 'په هغه وخت کې هارون د یوسلو درویشتو کالو په عمر و.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38471, 'Numbers 33:40', 'Numbers', 33, 40, 'د عراد کنعاني پاچا چې د کنعان په جنوب کې اوسېده، واورېدل چې اسراییلیان راروان دي.', 'د عراد کنعانی پاچا چې د کنعان په جنوب کې اوسېده، واورېدل چې اسراییلیان راروان دی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38472, 'Numbers 33:48', 'Numbers', 33, 48, 'او په اخر کې د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ.', 'او په اخر کې د مواب په داګونو کې د اردن د سیند په بله غاره اریحا ته مخامخ.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38473, 'Numbers 33:49', 'Numbers', 33, 49, 'د هغوی کمپ د بیت یشیموت څخه تر آبل شطیم پورې غزېدلی ؤ.', 'د هغوی کمپ د بیت یشیموت چخه تر ابل شطیم پورې غزېدلی و.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38474, 'Numbers 33:50', 'Numbers', 33, 50, 'کله چې د اسراییلو قوم د موآب په ډاګونو کې د اردن د سیند په غاړه اریحا ته مخامخ خېمې ودرولې وې، څښتن موسی ته وویل چې', 'کله چې د اسراییلو قوم د مواب په داګونو کې د اردن د سیند په غاره اریحا ته مخامخ خېمې ودرولې وې، چشتن موسی ته وویل چې', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38475, 'Numbers 33:51', 'Numbers', 33, 51, 'هغوی ته دا پیغام ورسوي: «کله چې تاسو د اردن د سیند څخه تېر شئ او کنعان ته ورننوځئ،', 'هغوی ته دا پیغام ورسوی: «کله چې تاسو د اردن د سیند چخه تېر شی او کنعان ته ورننوجی،', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38476, 'Numbers 33:52', 'Numbers', 33, 52, 'باید د هغه ځای ټول اوسېدونکي وشړئ. د هغوی ټول د تیږو او فلزي بتان او ټول عبادتځایونه له منځه یوسئ.', 'باید د هغه جای تول اوسېدونکی وشری. د هغوی تول د تیزو او فلزی بتان او تول عبادتجایونه له منجه یوسی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38477, 'Numbers 33:53', 'Numbers', 33, 53, 'هغه خاوره ونیسئ او په هغې کې واوسېږئ، ځکه چې هغه مې تاسو ته درکړې ده.', 'هغه خاوره ونیسی او په هغې کې واوسېزی، جکه چې هغه مې تاسو ته درکرې ده.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38478, 'Numbers 33:54', 'Numbers', 33, 54, 'هغه ځمکه د مختلفو قبیلو او طایفو ترمنځ د پچې له مخې ووېشئ، لویې طایفې ته زیاته ځمکه او کوچنۍ طایفې ته لږه ځمکه ورکړئ.', 'هغه جمکه د مختلفو قبیلو او طایفو ترمنج د پچې له مخې ووېشی، لویې طایفې ته زیاته جمکه او کوچنی طایفې ته لزه جمکه ورکری.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38479, 'Numbers 33:55', 'Numbers', 33, 55, 'که چېرې د هغه ځای ټول اوسېدونکي ونه شړئ، هغوی به ستاسو په سترګو کې د اغزیو او ستاسو په بدنونو کې به د کرکڼو په شان شي. هغوی به تل تاسو ته تکلیف درکوي.', 'که چېرې د هغه جای تول اوسېدونکی ونه شری، هغوی به ستاسو په سترګو کې د اغزیو او ستاسو په بدنونو کې به د کرکنو په شان شی. هغوی به تل تاسو ته تکلیف درکوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38480, 'Numbers 33:56', 'Numbers', 33, 56, 'که چېرې تاسو هغوی ونه شړئ، زه به تاسو تباه کړم لکه څنګه چې مې د هغوی د تباه کولو پلان جوړ کړی دی.»', 'که چېرې تاسو هغوی ونه شری، زه به تاسو تباه کرم لکه چنګه چې مې د هغوی د تباه کولو پلان جور کری دی.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38481, 'Joshua 19:1', 'Joshua', 19, 1, 'دوهمه پچه د شمعون د قبیلې د طایفو په نوم ووتله. د هغوی سیمه د یهودا په ځمکه کې پرته وه.', 'دوهمه پچه د شمعون د قبیلې د طایفو په نوم ووتله. د هغوی سیمه د یهودا په جمکه کې پرته وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38482, 'Joshua 19:2', 'Joshua', 19, 2, 'په هغې کې دا ځایونه شامل وو: بیرشبع (شبع)، مولاده،', 'په هغې کې دا جایونه شامل وو: بیرشبع (شبع)، مولاده،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38483, 'Joshua 19:3', 'Joshua', 19, 3, 'حزر شوعال، بالح، عاصم،', 'حزر شوعال، بالح، عاصم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38484, 'Joshua 19:4', 'Joshua', 19, 4, 'التولد، بتول، حرمه،', 'التولد، بتول، حرمه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38485, 'Joshua 19:5', 'Joshua', 19, 5, 'صقلغ، بیت مرکبوت، حزر سوسه،', 'صقلغ، بیت مرکبوت، حزر سوسه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38486, 'Joshua 19:6', 'Joshua', 19, 6, 'بیت لباعوت او شاروحن - د شاوخوا کلیو سره دیارلس ښارګوټي.', 'بیت لباعوت او شاروحن - د شاوخوا کلیو سره دیارلس شارګوتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38487, 'Joshua 19:7', 'Joshua', 19, 7, 'عین، رمون، عاتر او عاشان - د شاوخوا کلیو سره څلور ښارګوټي.', 'عین، رمون، عاتر او عاشان - د شاوخوا کلیو سره چلور شارګوتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38488, 'Joshua 19:8', 'Joshua', 19, 8, 'په دې سیمه کې په جنوب کې تر بعلت بییر (جنوبي رامه) پورې ټول ښارګوټي او کلي شامل وو. دا هغه ځمکه وه چې د شمعون د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', 'په دې سیمه کې په جنوب کې تر بعلت بییر (جنوبی رامه) پورې تول شارګوتی او کلی شامل وو. دا هغه جمکه وه چې د شمعون د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38489, 'Joshua 19:9', 'Joshua', 19, 9, 'څرنګه چې د یهودا برخه د هغوی د اړتیا له اندازې څخه زیاته وه، نو د هغه د سیمې یوه برخه د شمعون قبیلې ته ورکړل شوه.', 'چرنګه چې د یهودا برخه د هغوی د ارتیا له اندازې چخه زیاته وه، نو د هغه د سیمې یوه برخه د شمعون قبیلې ته ورکرل شوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38490, 'Joshua 19:10', 'Joshua', 19, 10, 'درېمه پچه د زبولون د قبیلې د طایفو په نوم ووتله. هغه ځمکه چې هغوی تر لاسه کړه د سارید پورې رسېدله.', 'درېمه پچه د زبولون د قبیلې د طایفو په نوم ووتله. هغه جمکه چې هغوی تر لاسه کره د سارید پورې رسېدله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38491, 'Joshua 19:11', 'Joshua', 19, 11, 'دا سرحد د هغه ځای څخه په لوېدیځه خوا کې مرعله ته تللی او د دباشه پورې رسېدلی او یقنعام ته نژدې ویالې ته تللی دی.', 'دا سرحد د هغه جای چخه په لوېدیجه خوا کې مرعله ته تللی او د دباشه پورې رسېدلی او یقنعام ته نژدې ویالې ته تللی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38492, 'Joshua 19:12', 'Joshua', 19, 12, 'دا سرحد د سارید ختیځې خواته د کسلوت تابور د سیمې پولې ته ګرځېدلی او دابره ته راوتلی او پورته تر یافیع پورې رسېدلی دی.', 'دا سرحد د سارید ختیجې خواته د کسلوت تابور د سیمې پولې ته ګرجېدلی او دابره ته راوتلی او پورته تر یافیع پورې رسېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38493, 'Joshua 19:13', 'Joshua', 19, 13, 'بیا دا سرحد د ختیځ خواته د جت حافر او عت قاصین ته تللی، رمون ته راوتلی او د نیعه خواته ګرځېدلی دی.', 'بیا دا سرحد د ختیج خواته د جت حافر او عت قاصین ته تللی، رمون ته راوتلی او د نیعه خواته ګرجېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38494, 'Joshua 19:14', 'Joshua', 19, 14, 'په شمال کې دا سرحد د حناتون خواته ګرځېدلی او د یفتح ییل په دره کې ختم شوی دی.', 'په شمال کې دا سرحد د حناتون خواته ګرجېدلی او د یفتح ییل په دره کې ختم شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38495, 'Joshua 19:15', 'Joshua', 19, 15, 'زبولون د شاوخوا کلیو سره دولس ښارګوټي درلودل. د هغو څخه ځینې یې دا وو: قطه، نهلال، شمرون، یداله او بیت لحم.', 'زبولون د شاوخوا کلیو سره دولس شارګوتی درلودل. د هغو چخه جینې یې دا وو: قطه، نهلال، شمرون، یداله او بیت لحم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_19_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
